function numberToken(s){s=String(s).replace(/[ $\u00a0]/g,'');if(/,\d{3}$/.test(s)&&!s.includes('.'))s=s.replace(/,/g,'');else if(/,\d{1,2}$/.test(s))s=s.replace(',','.');return num(s)}
function commandDate(text){const low=text.toLowerCase(),now=new Date();if(/вчера/.test(low)){now.setDate(now.getDate()-1);return dkey(now)}if(/сегодня/.test(low))return dkey(now);let m=low.match(/\b(20\d{2})-(\d{1,2})-(\d{1,2})\b/);if(m)return m[1]+'-'+m[2].padStart(2,'0')+'-'+m[3].padStart(2,'0');m=low.match(/\b(\d{1,2})[.\/](\d{1,2})[.\/](20\d{2})\b/);if(m)return m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0');m=low.match(/\b(\d{1,2})\s+(января|февраля|марта|апреля|мая|июня|июля|августа|сентября|октября|ноября|декабря)(?:\s+(20\d{2}))?/);if(m)return (m[3]||now.getFullYear())+'-'+String(MONTHS[m[2]]+1).padStart(2,'0')+'-'+m[1].padStart(2,'0');return null}
