function payerHint(text){const low=text.toLowerCase(),company=/карт\w*\s+компан|деньги компании|оплатил\w*\s+компан/.test(low),personal=/личн|сво[иим]|мо[яей]\s+карт/.test(low);let payer=company?'company':'me',reimb=owner()?'none':'pending';if(/не\s+(?:нужно|надо)\s+возмещ|без\s+возмещ/.test(low)||company)reimb='none';else if(/уже\s+(?:вернули|возместили)|возмещено/.test(low))reimb='paid';else if(personal||/возмещ|вернуть|вернут\s+за/.test(low))reimb='pending';return{payer,reimb}}
