function routeFromText(text){const m=text.match(/(?:рейс|маршрут)\s+(.+?)(?:\s*[-–—→>]\s*|\s+в\s+)(.+?)(?=\s*[,;]|\s+\$?\d|$)/i);return m?{from:m[1].trim(),to:m[2].trim()}:{from:'',to:''}}
