 if(/рейс|маршрут|rate confirmation/.test(low)&&!/покаж|сколько/.test(low)){const route=routeFromText(text),m=low.match(/(\d+(?:[.,]\d+)?)\s*(?:груж[её]н[a-zа-яё]*\s*)?(?:миль|мил[ьяию]|mi)(?![a-zа-яё])/),dead=low.match(/(\d+(?:[.,]\d+)?)\s*(?:порожн[a-zа-яё]*|deadhead|empty)(?![a-zа-яё])/);aiExchange(text,amount?'Черновик рейса на '+fmt(amount)+'. Проверьте маршрут, оплату и мили.':'Не нашёл оплату рейса. Введите её в черновике перед сохранением.');return loadForm({pay:amount,ts,miles:m?numberToken(m[1]):0,dead:dead?numberToken(dead[1]):0,...route})}
 if(/заправ|топлив|дизель|diesel|\bfuel\b/.test(low)&&!/покаж|сколько|отч[её]т/.test(low)){const g=low.match(/(\d+(?:[.,]\d+)?)\s*(?:галлон[a-zа-яё]*|гал\.?|gallons?|gal)(?![a-zа-яё])/),merchant=(text.match(/\b(Love'?s|Pilot|Flying J|TA|Petro|Shell|Speedway|Casey'?s)\b/i)||[])[0]||'';aiExchange(text,amount?'Черновик заправки на '+fmt(amount)+'. Проверьте галлоны и штат.':'Не нашёл полную сумму заправки. Введите её в черновике.');return fuelForm({cost:amount,gal:g?numberToken(g[1]):0,ts,merchant,state:fuelState(text),tax:true})}
