 if(amount){const h=expenseHint(text),payer=payerHint(text);aiExchange(text,'Черновик: '+(h.title||'Расход')+' — '+fmt(amount)+', категория «'+catLabel(h.cat)+'». Проверьте назначение и возмещение.');return expenseForm({amount,ts,merchant:'',title:h.title,cat:h.cat,tax:owner(),...payer})}
