function toggleVoice(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return note('Диктовка не поддерживается. Введите текст вручную.');if(voiceRec){voiceRec.stop();return}const field=$('#s4AiText');if(!field)return;const base=field.value.trim();voiceRec=new SR();voiceRec.lang='ru-RU';voiceRec.interimResults=true;voiceRec.continuous=false;voiceRec.onstart=()=>{clearTimeout(voiceTimer);voiceRec._started=true;scanStatus('Говорите. Диктовка появится в поле — отправка отдельной кнопкой.');const b=$('[data-s4="voice"]');if(b)b.classList.add('recording')};voiceRec.onresult=e=>{let said='';for(let i=e.resultIndex;i<e.results.length;i++)said+=e.results[i][0].transcript+' ';field.value=(base+' '+said.trim()).trim()};voiceRec.onerror=ev=>{clearTimeout(voiceTimer);scanStatus('Голос не распознан'+(navigator.onLine?'':': в этом браузере диктовка требует интернет')+'. Введите текст вручную.');console.warn('Speech recognition:',ev.error)};voiceRec.onend=()=>{clearTimeout(voiceTimer);voiceRec=null;const b=$('[data-s4="voice"]');if(b)b.classList.remove('recording');if(field.value.trim()!==base)scanStatus('Диктовка добавлена в поле. Проверьте текст и нажмите «Разобрать».')};try{voiceRec.start();voiceTimer=setTimeout(()=>{if(voiceRec&&!voiceRec._started){scanStatus('Диктовка не запустилась в этом браузере. Проверьте микрофон и интернет или введите текст вручную.');try{voiceRec.stop()}catch(e){}voiceRec=null}},5000)}catch(e){clearTimeout(voiceTimer);voiceRec=null;scanStatus('Не удалось запустить диктовку. Введите текст вручную.')}}
